(()=>{
const q=s=>document.querySelector(s),all=s=>[...document.querySelectorAll(s)],personal=()=>q('#applicant').value==='individual';
const fields=s=>[...s.querySelectorAll('input,select,textarea')].filter(e=>!e.closest('.country-picker'));
// Preserve older saved answers when moving fields between steps.
let draft=null,values=new Map();try{draft=JSON.parse(localStorage.getItem('finsyndeo-whole-review-unified-draft-v1')||'null');if(draft&&draft.version<3)draft.screens.forEach(st=>{const s=q('[data-screen="'+st.id+'"]');if(s)fields(s).forEach((e,i)=>{if(st.values[i])values.set(e,st.values[i]);});});}catch(e){}
const company=q('[data-screen="5"]'),individual=q('[data-screen="24"]');
const bank=q('#bank-list').closest('section');const bankPage=document.createElement('div');bankPage.className='screen';bankPage.dataset.screen=39;bankPage.hidden=true;bankPage.innerHTML='<h1>Existing banking relationships</h1><p class="lead">Tell us about any existing accounts. This information is optional.</p>';bankPage.append(bank);q('main').append(bankPage);
const currentBank=q('#pb-current-bank').closest('label'),currentDetail=q('#pb-current-bank-details');q('[data-screen="21"] .panel').append(currentBank,currentDetail);
const summary=document.createElement('div');summary.className='screen';summary.dataset.screen=40;summary.hidden=true;summary.innerHTML='<h1>Your Assessment Summary</h1><p class="lead">Review your answers. Edit any section or confirm to find matching institutions.</p><div id="complete-summary"></div><div id="company-confirm"></div><div id="personal-confirm"></div><div class="actions"><button type="button" id="summary-back">Back to contact details</button><button type="button" id="summary-confirm" class="primary">Confirm & find matching institutions</button></div>';q('main').append(summary);
q('#review-summary').closest('section').hidden=true;q('#pb-summary').closest('section').hidden=true;
q('#company-confirm').append(q('#accuracy').closest('section'));q('#company-confirm').append(q('#submit'));q('#submit').hidden=true;
q('#personal-confirm').append(q('#pb-accuracy').closest('label'),q('#pb-meeting'));q('#personal-confirm').insertAdjacentHTML('beforeend','<p class="hint">SOPHIMA reviews introduction requests. You approve the institution and information to share.</p>');
company.querySelector('h1').textContent='Contact details';company.querySelector('.lead').textContent='Tell us who is authorised to represent the entity.';individual.querySelector('h1').textContent='Contact details';individual.querySelector('.lead').textContent='How can we contact you about your request?';
q('#representative-role').closest('section').after(company.querySelector('.actions'));
labels[5]='Contact';labels[24]='Contact';labels[39]='Existing banking';labels[40]='Your Assessment Summary';
const oldFlow=activeFlow;activeFlow=function(){let f=oldFlow();if(!personal())f.splice(f.indexOf(4),0,39);return [...f,40];};
let personalSubmit=null;
function contactValid(){const name=personal()?q('#pb-name'):q('#contact-name'),email=personal()?q('#pb-email'):q('#contact-email');if(!name.value.trim()||!email.value.trim()||!email.checkValidity()){note('Please enter your name and a valid email address.');email.focus();return false;}if(!personal()&&(!q('#representative-role').value||!q('#representative-authority').checked||(q('#representative-firm').required&&!q('#representative-firm').value.trim()))){note('Please provide your relationship to the entity and confirm your authority to act.');return false;}return true;}
function buildSummary(){const host=q('#complete-summary');host.replaceChildren();for(const n of activeFlow().filter(n=>![0,1,40].includes(n))){const s=q('[data-screen="'+n+'"]');const panel=document.createElement('section');panel.className='panel';const h=document.createElement('h2');h.textContent=labels[n];const edit=document.createElement('button');edit.className='mini';edit.textContent='Edit '+labels[n];edit.onclick=()=>showPage(n);const dl=document.createElement('dl');dl.className='summary';const seen=new Set();for(const e of s.querySelectorAll('input,select,textarea')){if(e.type==='search'||e.type==='hidden'||e.closest('.country-picker')||e.id==='accuracy'||e.id==='pb-accuracy')continue;let a=e.parentElement,hidden=false;while(a&&a!==s){if(a.hidden){hidden=true;break;}a=a.parentElement;}if(hidden)continue;let title=e.closest('label')?.querySelector('span')?.textContent||e.getAttribute('aria-label')||e.closest('fieldset')?.querySelector('legend')?.textContent||'';let val=e.value;if(e.type==='checkbox'||e.type==='radio'){if(!e.checked)continue;val=e.parentElement.textContent.trim();title=e.closest('fieldset')?.querySelector('legend')?.textContent||'Selected';}if(!title||!val||val==='Select…')continue;const key=title+val;if(seen.has(key))continue;seen.add(key);const dt=document.createElement('dt'),dd=document.createElement('dd');dt.textContent=title;dd.textContent=val;dl.append(dt,dd);}for(const picker of s.querySelectorAll('.country-picker')){const chips=[...picker.querySelectorAll('.chip')].map(c=>c.textContent.replace(/ ×$/,''));if(chips.length){const dt=document.createElement('dt'),dd=document.createElement('dd');dt.textContent=picker.parentElement.querySelector('span')?.textContent||'Countries';dd.textContent=chips.join(', ');dl.append(dt,dd);}}panel.append(h,edit,dl);host.append(panel);}const intro=document.createElement('section');intro.className='panel';intro.innerHTML='<h2>Applicant & service</h2>';const p=document.createElement('p');p.textContent=personal()?'Individual — Private banking':q('#applicant').value==='institution'?'Financial institution — Correspondent / payment accounts':q('#account-type').selectedOptions[0].textContent;const button=document.createElement('button');button.textContent='Edit applicant details';button.onclick=()=>showPage(1);intro.append(p,button);if(!personal()){const details=document.createElement('p');details.textContent=[q('#company-name').value,q('#incorporation').value,q('#registration').value,q('#entity-type').value].filter(Boolean).join(' · ');intro.append(details);}host.prepend(intro);q('#company-confirm').hidden=personal();q('#personal-confirm').hidden=!personal();}
const oldRefresh=refreshFlow;refreshFlow=function(){oldRefresh();summary.querySelector('.actions').innerHTML='<button type="button" id="summary-back">Back to contact details</button><button type="button" id="summary-confirm" class="primary">Confirm & find matching institutions</button>';const pb=q('#pb-submit');if(pb)personalSubmit=pb.onclick;for(const [n,prev] of [[5,4],[24,23]]){let a=q('[data-screen="'+n+'"] .actions');if(!a){a=document.createElement('div');a.className='actions';q('[data-screen="'+n+'"]').append(a);}a.replaceChildren();const back=document.createElement('button'),next=document.createElement('button');back.textContent='Back';back.onclick=()=>showPage(prev);next.textContent='Review my assessment';next.className='primary';next.onclick=()=>{if(contactValid())showPage(40);};a.append(back,next);}q('#summary-back').onclick=()=>showPage(personal()?24:5);q('#summary-confirm').onclick=()=>{if(!contactValid())return;if(personal())personalSubmit();else q('#submit').click();};const result=q('[data-screen="6"] .actions button');result.onclick=()=>showPage(40);};window.refreshFlow=refreshFlow;
const oldShow=showPage;showPage=function(n){if(n===40){if(!contactValid())return;currentPage=40;all('.screen').forEach(s=>s.hidden=s.dataset.screen!=='40');q('#feedback').textContent='';refreshFlow();buildSummary();scrollTo(0,0);return;}oldShow(n);};
if(draft&&draft.version<3){draft.screens=all('.screen').map(s=>{const old=draft.screens.find(x=>x.id===s.dataset.screen);return {id:s.dataset.screen,values:fields(s).map(e=>values.get(e)||{value:e.value,checked:e.checked}),pickers:old?.pickers||[]};});draft.version=3;localStorage.setItem('finsyndeo-whole-review-unified-draft-v1',JSON.stringify(draft));}
refreshFlow();
})();
